"""Tests for the static dashboard (`docs/index.html`) generated by `earnings_cal.dashboard`."""

from __future__ import annotations

import json
import re
from datetime import date, time
from pathlib import Path

from earnings_cal.build import render_index_html, write_index_html
from earnings_cal.dashboard import (
    build_dashboard_payload,
    load_events_from_ics_for_dashboard,
    render_dashboard_html,
    serialize_event_for_dashboard,
)
from earnings_cal.markets import get_market_registry
from earnings_cal.models import Event, EventKind, EventTiming
from earnings_cal.results import EarningsResultRow

_EMBEDDED_JSON_RE = re.compile(
    r'<script id="dashboard-data" type="application/json">\s*(.*?)\s*</script>',
    re.S,
)


def _extract_embedded_json(html_text: str) -> dict:
    match = _EMBEDDED_JSON_RE.search(html_text)
    assert match is not None, "Expected <script id='dashboard-data' type='application/json'> in HTML"
    return json.loads(match.group(1))


def test_dashboard_generation_from_fixture_data_and_embedded_json_parses(tmp_path: Path) -> None:
    """Verify dashboard renders all 5 sections from fixture data, embedded JSON parses, and output is deterministic."""
    markets = list(get_market_registry().values())

    events_by_market = {
        "us": [
            Event(
                market="us",
                ticker="AAPL",
                title="AAPL Q4 2026 Earnings",
                date=date(2026, 11, 12),
                kind=EventKind.EARNINGS,
                timing=EventTiming.AMC,
                market_timezone="America/New_York",
                source_url="https://investor.apple.com/",
                quarter=4,
                fiscal_year=2026,
            ),
            Event(
                market="us",
                ticker="MSFT",
                title="MSFT Earnings Call",
                date=date(2026, 11, 15),
                kind=EventKind.EARNINGS,
                timing=EventTiming.EXACT,
                time=time(17, 0),
                duration_minutes=60,
                market_timezone="America/New_York",
            ),
        ],
        "ljse": [
            Event(
                market="ljse",
                ticker="KRKG",
                title="KRKG Dividend Payment",
                date=date(2026, 11, 20),
                kind=EventKind.DIVIDEND_PAYMENT,
                timing=EventTiming.UNKNOWN,
                market_timezone="Europe/Ljubljana",
                amount_per_share=7.50,
                source_url="https://seonet.ljse.si/",
            ),
        ],
        "macro": [
            Event(
                market="macro",
                ticker="FOMC",
                title="FOMC decision",
                date=date(2026, 12, 8),
                end_date=date(2026, 12, 9),
                decision_date=date(2026, 12, 9),
                decision_time=time(14, 0),
                kind=EventKind.CENTRAL_BANK_MEETING,
                timing=EventTiming.UNKNOWN,
                market_timezone="America/New_York",
                source_url="https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm",
            ),
        ],
    }

    status_data = {
        "overall_healthy": False,
        "markets": {
            "us": {
                "healthy": True,
                "stale": False,
                "last_success_date": "2026-11-11",
                "age_days": 0.0,
                "upcoming_events": 2,
                "errors": [],
            },
            "ljse": {
                "healthy": False,
                "stale": True,
                "last_success_date": "2026-11-01",
                "age_days": 10.0,
                "upcoming_events": 1,
                "errors": ["SEOnet timeout"],
            },
            "macro": {
                "healthy": True,
                "stale": False,
                "last_success_date": "2026-11-11",
                "age_days": 0.0,
                "upcoming_events": 1,
                "errors": [],
            },
        },
        "sources": {
            "api": {
                "healthy": True,
                "stale": False,
                "last_success_date": "2026-11-11",
                "age_days": 0.0,
                "errors": [],
            },
            "seonet": {
                "healthy": False,
                "stale": True,
                "last_success_date": "2026-11-01",
                "age_days": 10.0,
                "errors": ["SEOnet feed unreachable"],
            },
        },
    }

    changes_records = [
        {
            "run_date": "2026-11-11",
            "change_type": "date_changed",
            "uid": "us-aapl-2026q4-earnings@earnings-cal.local",
            "market": "us",
            "ticker": "AAPL",
            "old_date": "2026-11-10",
            "new_date": "2026-11-12",
            "old_summary": "AAPL Q4 2026 Earnings",
            "new_summary": "AAPL Q4 2026 Earnings",
            "details": "Date moved from 2026-11-10 to 2026-11-12",
        },
        {
            "run_date": "2026-11-11",
            "change_type": "removed",
            "uid": "ljse-petg-2026q3-earnings@earnings-cal.local",
            "market": "ljse",
            "ticker": "PETG",
            "old_date": "2026-11-18",
            "new_date": None,
            "old_summary": "PETG Q3 2026 Earnings",
            "new_summary": None,
            "details": "Removed from feed inside window",
        },
    ]

    results_rows = [
        EarningsResultRow(
            market="us",
            ticker="NVDA",
            report_date=date(2026, 10, 28),
            fiscal_period="2026Q3",
            eps_estimate=0.75,
            eps_actual=0.81,
            surprise_pct=8.00,
            price_move_1d_pct=4.52,
            recorded_at="2026-11-11T12:00:00Z",
            manual_notes="",
        ),
        EarningsResultRow(
            market="ljse",
            ticker="KRKG",
            report_date=date(2026, 10, 20),
            fiscal_period="2026Q3",
            eps_estimate=None,
            eps_actual=None,
            surprise_pct=None,
            price_move_1d_pct=1.20,
            recorded_at="2026-11-11T12:00:00Z",
            manual_notes="Preliminary 9M report",
        ),
    ]

    html_out = render_index_html(
        markets=markets,
        display_timezone="Europe/Ljubljana",
        events_by_market=events_by_market,
        status_data=status_data,
        changes_records=changes_records,
        results_rows=results_rows,
    )

    # 1. Feed links with webcal:// subscribe buttons per market
    assert 'id="section-feeds"' in html_out
    assert "webcal://lukagorenjak.github.io/AutomaticStockEarningsAppleCalendar/us.ics" in html_out
    assert "webcal://lukagorenjak.github.io/AutomaticStockEarningsAppleCalendar/ljse.ics" in html_out
    assert "webcal://lukagorenjak.github.io/AutomaticStockEarningsAppleCalendar/macro.ics" in html_out
    assert "webcal://lukagorenjak.github.io/AutomaticStockEarningsAppleCalendar/eu.ics" in html_out
    assert 'class="btn-subscribe webcal-link"' in html_out

    # 2. Upcoming events table, sortable and filterable by market and kind, with local time
    assert 'id="section-upcoming"' in html_out
    assert 'id="upcoming-table"' in html_out
    assert 'id="filter-market"' in html_out
    assert 'id="filter-kind"' in html_out
    assert 'data-sort="date"' in html_out
    assert 'data-market="us"' in html_out
    assert 'data-kind="dividend_payment"' in html_out
    assert 'data-kind="central_bank_meeting"' in html_out
    # Exact time event converted from 17:00 ET -> 23:00 CET in Europe/Ljubljana
    assert "23:00 CET" in html_out
    # Multi-day FOMC decision time converted from 14:00 ET -> 20:00 CET
    assert "<code>2026-12-08</code> <small>&rarr; 2026-12-09</small>" in html_out
    assert "20:00 CET" in html_out

    # 3. Recent changes from the changelog
    assert 'id="section-changes"' in html_out
    assert 'id="changes-table"' in html_out
    assert "2026-11-10 &rarr; 2026-11-12" in html_out
    assert "badge-date_changed" in html_out
    assert "badge-removed" in html_out

    # 4. Results history with surprise and one-day move
    assert 'id="section-results"' in html_out
    assert 'id="results-table"' in html_out
    assert "+8.00%" in html_out
    assert "+4.52%" in html_out
    assert "Preliminary 9M report" in html_out

    # 5. Data health bar from status.json showing last update per source, red when stale
    assert 'id="health-bar"' in html_out
    assert "health-stale" in html_out
    assert "health-ok" in html_out
    assert "Source: SEONET" in html_out
    assert "(STALE · last update: 2026-11-01)" in html_out

    # Dark mode & responsive CSS rules present, no external CDNs
    assert "@media (prefers-color-scheme: dark)" in html_out
    assert "@media (max-width: 640px)" in html_out
    assert "https://cdn." not in html_out

    # Embedded JSON parses cleanly and matches rendered data
    parsed_json = _extract_embedded_json(html_out)
    assert parsed_json["display_timezone"] == "Europe/Ljubljana"
    assert len(parsed_json["feeds"]) == len(markets)
    assert {f["id"] for f in parsed_json["feeds"]} == {"us", "ljse", "macro", "eu"}
    assert len(parsed_json["upcoming_events"]) == 4
    assert len(parsed_json["recent_changes"]) == 2
    assert len(parsed_json["results"]) == 2
    assert parsed_json["status"]["sources"]["seonet"]["stale"] is True
    assert parsed_json["status"]["sources"]["api"]["stale"] is False

    # Deterministic output check: second render is byte-for-byte identical, write_index_html returns False on 2nd write
    html_second = render_index_html(
        markets=markets,
        display_timezone="Europe/Ljubljana",
        events_by_market=events_by_market,
        status_data=status_data,
        changes_records=changes_records,
        results_rows=results_rows,
    )
    assert html_out == html_second

    out_file = tmp_path / "docs" / "index.html"
    assert write_index_html(
        markets=markets,
        output_path=out_file,
        display_timezone="Europe/Ljubljana",
        events_by_market=events_by_market,
        status_data=status_data,
        changes_records=changes_records,
        results_rows=results_rows,
    ) is True
    assert write_index_html(
        markets=markets,
        output_path=out_file,
        display_timezone="Europe/Ljubljana",
        events_by_market=events_by_market,
        status_data=status_data,
        changes_records=changes_records,
        results_rows=results_rows,
    ) is False


def test_dashboard_empty_data_states() -> None:
    """Verify dashboard renders cleanly when there are no events, no changelog entries, and no results yet."""
    markets = list(get_market_registry().values())
    empty_html = render_index_html(
        markets=markets,
        display_timezone="Europe/Ljubljana",
        events_by_market={},
        status_data={"overall_healthy": True, "markets": {}, "sources": {}},
        changes_records=[],
        results_rows=[],
    )

    assert "No upcoming events match the current filter." in empty_html
    assert "No changelog entries recorded yet." in empty_html
    assert "No post-earnings results recorded yet." in empty_html

    parsed = _extract_embedded_json(empty_html)
    assert parsed["upcoming_events"] == []
    assert parsed["recent_changes"] == []
    assert parsed["results"] == []
    assert len(parsed["feeds"]) == len(markets)
